use std::fmt;

#[derive(Debug, PartialEq)]
enum CountError {
    Empty,
    NotANumber(String),
    TooBig(u64),
}

impl fmt::Display for CountError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CountError::Empty => write!(f, "no count given"),
            CountError::NotANumber(t) => write!(f, "{t:?} is not a count"),
            CountError::TooBig(n) => write!(f, "{n} is more than 10000"),
        }
    }
}

impl std::error::Error for CountError {}

fn parse_count(text: &str) -> Result<u32, CountError> {
    let t = text.trim();
    if t.is_empty() {
        return Err(CountError::Empty);
    }
    let n: u64 = t.parse().map_err(|_| CountError::NotANumber(t.to_string()))?;
    if n > 10_000 {
        return Err(CountError::TooBig(n));
    }
    Ok(n as u32)
}

unitTests:
fn is_error<E: std::error::Error>(_: &E) -> bool { true }

test("good counts", || {
    check_eq(parse_count(" 42 "), Ok(42));
    check_eq(parse_count("0"), Ok(0));
    check_eq(parse_count("10000"), Ok(10000));
});

test("each kind of failure", || {
    check_eq(parse_count("   "), Err(CountError::Empty));
    check_eq(parse_count(" abc "), Err(CountError::NotANumber("abc".to_string())));
    check_eq(parse_count("-3"), Err(CountError::NotANumber("-3".to_string())));
    check_eq(parse_count("12000"), Err(CountError::TooBig(12000)));
});

test("messages", || {
    check_eq(CountError::Empty.to_string(), "no count given");
    check_eq(CountError::NotANumber("abc".into()).to_string(), "\"abc\" is not a count");
    check_eq(CountError::TooBig(12000).to_string(), "12000 is more than 10000");
    check(is_error(&CountError::Empty));
});

